  "dev.disable": "تعطيل",
  "dev.noContent": "التسليم يحمل حدثًا ومعرّفًا ووقتًا. ولا يحمل أبدًا ملاحظة ولا نصًا ولا أي شيء عن جلسة، فتسريب رابط النقطة لا يسرّب شيئًا. اجمع ما تحتاجه بمفتاح نستطيع إلغاءه.",
  "dev.secretOnce": "يُعرض سر التوقيع مرة واحدة. وقّع به: الترويسة هي t=الوقت,v1=hmac على الوقت ونقطة والمحتوى.",
  "dev.deliveriesTitle": "التسليمات الأخيرة",
  "dev.deliveriesEmpty": "لا تسليمات بعد.",
  "dev.delivered": "سُلّم",
  "dev.pending": "قيد الانتظار",
  "dev.attempts": "{count} محاولة",
  "devs.title": "ابنِ على طبقة السجل السريري",
  "devs.body": "خمسة أشياء تستطيع فعلها بواجهتنا، كل واحدة مسار له شاشة في طرفه. وإن لم يكن ما تريده هنا فليس لأننا لم نتفرغ له.",
  "devs.useCase3": "قراءة سجل بتفويض",
  "devs.useCase3Body": "معالجك يقرأ سجل المريض تمامًا كما يقرأه معالجنا، لأن المريض فوّضه بالاسم ويستطيع سحب التفويض. لا يوجد مفتاح يقرأ سجلًا: المفتاح يخبرك من يستطيع، ومعالجك يسجّل الدخول ليفعل ذلك. والمريض يستطيع أخذ سجله والمغادرة في أي وقت، بما في ذلك مغادرتك.",
  "devs.useCase4": "كتابة الجلسة",
  "devs.useCase4Body": "جلسة أُجريت على منصتك تُسجّل في ملفنا، منسوبة إلى منصتك. نسجّل أنها حدثت ومتى ومع من. ولا نقبل ملاحظة ولا نصًا من خادم، لأن المحتوى في الملف يحتاج معالجًا اعتمد ذلك النص بعينه.",
  "devs.useCase5": "تسليم الملاحظة",
  "devs.useCase5Body": "ملاحظة نهائية اعتمدها معالج، تجمعها أنت. لا مسودة أبدًا. ولا مخرجات نموذج لم يوقّعها أحد. الاستدعاء يخبرك بوجودها، والمفتاح يجمعها.",
  "devs.widget": "اللوحة المدمجة",
  "devs.widgetBody": "زر في منتجك يفتح لوحتنا في نافذتها الخاصة، مسجّلًا دخول معالجك، بلا تسجيل دخول ثانٍ وبلا أي بيانات اعتماد منّا في يدك. وهي نافذة لا إطار مدمج بقصد: السجل داخل صفحة تتحكم فيها أنت سجل يمكن خدع أحد للتصرف فيه. وبلا فيديو افتراضيًا، لأن لديك فيديو خاص بك، ووجود منتجي فيديو على شاشة واحدة أسوأ للمريض من أي منهما وحده.",
  "devs.keysNote": "المفاتيح مُبصمة، ومحدودة باستخدام واحد في المرة، وقابلة للتبديل، وتُصدر بعد اتصال. لا يوجد مفتاح ذاتي الخدمة، ولا يرى المعالج مفتاحًا أبدًا.",
  "devs.example": "مثال",
  "devs.getStarted": "اطلب حسابًا",
  "devs.promises": "الوعود الأربعة التي قطعتها هذه الصفحة قبل وجود أي من هذا",
  "devs.promisesBody": "كانت شروط فتح واجهة برمجية من الأصل. كل وعد منها يسمي الآن ما يحفظه، حتى تتحقق بنفسك بدلًا من أن تثق.",
  "devs.promise1": "إصدار لا يتغير من تحتك",
  "devs.promise1Body": "كل مسار يحمل v1. نضيف صلاحية ولا نعيد تشكيل استجابة، والمفتاح يسمي الصلاحيات التي صدر بها، فلا تصل قدرة جديدة داخل طلب تستخدمه بالفعل.",
  "devs.promise2": "هوية لا تتصادم",
  "devs.promise2Body": "منصتان ستُرسلان إلينا مريضًا اسمه P123. مرجعك يُحفظ على حسابك ويُحلّ داخله فقط، فمرجعك ومرجعهم صفّان مختلفان ولا يمكن لأحدهما الوصول إلى الآخر.",
  "devs.promise3": "موافقة تبقى قائمة عبر الحدود",
  "devs.promise3Body": "لا مفتاح يقرأ سجلًا. المفتاح يسأل من يحق له القراءة، والجواب هو المعالجون الذين منحهم المريض بالاسم. ثم يسجّل معالجك دخوله بنفسه ليقرأ، وإلغاء المنح يغلق هذا الباب في اللحظة نفسها التي يغلق فيها بابنا.",
  "devs.promise4": "سجل تدقيق على الجانبين",
  "devs.promise4Body": "كل طلب يُسجَّل بالمفتاح الذي أجراه، وفي حالة الإطلاق بالمعالج الذي جرى بالنيابة عنه. وقراءة السجل تظهر في سجل وصول المريض نفسه، كما تظهر قراءتنا، وتسمي منصتك.",
  "devs.limits": "ما لا توجد له نقطة وصول",
  "devs.limitsBody": "ليس مؤجلًا ولا على خطة: لا يوجد مسار ولا وسيط يقبله. لا قائمة بمن هو منضم في أي جهة. لا قائمة بمرضى أحد. لا سجل يقرأه مفتاح. لا ملاحظة لم يعتمدها معالج. لا نص جلسة نقبله من خادم. لا محتوى في استدعاء.",
  "devs.rateNote": "المفاتيح الحقيقية محدودة بعدد طلبات في الدقيقة، وتجاوز الحد يوقف المفتاح بدلًا من إبطائه. ابنِ على طلب واحد داخل مسار واحد، لا على مسح شامل.",
  "acheckin.nav": "رسائل الاطمئنان",
  "acheckin.title": "رسائل الاطمئنان",
  "acheckin.body": "رسالة قصيرة تسأل عن حال الشخص، على جدول. كان التواتر مطلبًا وكان الحكم المرافق له أن نتحقق منه لا أن نفترضه، فكل رقم هنا لك أن تغيّره، ومعدل الإيقاف هو ما يجب مراقبته.",
  "acheckin.rate": "معدل الإيقاف",
  "acheckin.rateBody": "{muted} من {reachable} ممن يمكن مراسلتهم أوقفوا هذه الرسائل. وفوق {halt} تتوقف القناة عن الإرسال للجميع، لأن الاستمرار عندها اختيار للخطأ مع الكل.",
  "acheckin.halted": "القناة متوقفة. أوقفها عدد كافٍ من الناس فتوقفت من نفسها.",
  "acheckin.sent": "أُرسلت {count}",
