  "acheckin.noBodies": "ما كتبه الناس ليس على هذه الشاشة ولا على أي شاشة. الرد المقلق يذهب إلى معالجهم عبر مسار الأزمة، وما عدا ذلك يُحفظ ولا يقرأه أحد.",
